package com.medtrack.inventory.entity; import jakarta.persistence.*; import java.time.Instant; import java.util.*;
@Entity @Table(name="idempotency_keys") public class IdempotencyKey { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="idempotency_key",nullable=false) private String key; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="request_path",nullable=false) private String requestPath; @Column(name="request_fingerprint",nullable=false) private String requestFingerprint; @Column(name="response_status") private Integer responseStatus; @Column(name="response_body") private String responseBody; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(name="expires_at",nullable=false) private Instant expiresAt; protected IdempotencyKey(){} public IdempotencyKey(String key,UUID userId,String path,String fingerprint,Instant expiresAt){this.key=key;this.userId=userId;requestPath=path;requestFingerprint=fingerprint;this.expiresAt=expiresAt;} public String getRequestFingerprint(){return requestFingerprint;} public Integer getResponseStatus(){return responseStatus;} public String getResponseBody(){return responseBody;} public void complete(int status,String body){responseStatus=status;responseBody=body;} }
